          </Message>
        ) : (
          <Message key={message.id}>
            <MessageContent>
              <Streamdown
                controls={false}
                components={components}
                isAnimating={busy && message === messages.at(-1)}
              >
                {getMessageText(message)}
              </Streamdown>
            </MessageContent>
          </Message>
