                <Trace>
                  {rows.map((part, index) =>
                    part.type === "reasoning" ? (
                      <ThinkingRow
                        key={index}
                        text={part.text}
                        running={streaming && part.state === "streaming"}
                      />
                    ) : part.type === "tool-runCommand" ? (
                      <ToolRow
                        key={part.toolCallId}
                        part={part}
                        streaming={streaming}
                        defaultOpen={index === 2}
                      />
                    ) : null
                  )}
                  {sources.length > 0 && (
                    <SourcesRow
                      sources={sources}
                      running={streaming && text.length === 0}
                    />
                  )}
                </Trace>
              )}
              {text && <p>{text}</p>}
            </MessageContent>
          </Message>
        )
      })}
      {!busy && (
        <Button
          variant="outline"
          size="sm"
          className="mt-auto self-start"
          onClick={() => {
            setMessages([])
            sendMessage(question)
          }}
        >
          Replay
        </Button>
      )}
    </div>
  )
}
