export function TraceDemo() {
  const { messages, sendMessage, setMessages, status } = useChat({
    messages: transcript,
    transport,
  })
  const busy = status === "submitted" || status === "streaming"

  return (
    <div className="flex min-h-72 w-full max-w-sm flex-col gap-4 py-6 text-sm">
      {messages.map((message) => {
        if (message.role === "user") {
          return (
            <Message key={message.id} align="end">
              <MessageContent>
                <Bubble align="end" variant="muted">
                  <BubbleContent>{getMessageText(message)}</BubbleContent>
                </Bubble>
              </MessageContent>
            </Message>
          )
        }

        const streaming = busy && message === messages.at(-1)
        const rows = message.parts.filter(
          (part) => part.type === "reasoning" || part.type === "tool-runCommand"
        )
        const sources = message.parts.filter(
          (part) => part.type === "source-url"
        )
        const text = getMessageText(message)

        return (
          <Message key={message.id}>
            <MessageContent className="gap-4">
              {rows.length + sources.length > 0 && (
                <Trace>
                  {rows.map((part, index) =>
                    part.type === "reasoning" ? (
                      <ThinkingRow
                        key={index}
                        text={part.text}
                        running={streaming && part.state === "streaming"}
                      />
                    ) : part.type === "tool-runCommand" ? (
                      <ToolRow
                        key={part.toolCallId}
                        part={part}
                        streaming={streaming}
                        defaultOpen={index === 2}
                      />
                    ) : null
                  )}
                  {sources.length > 0 && (
                    <SourcesRow
                      sources={sources}
                      running={streaming && text.length === 0}
                    />
                  )}
                </Trace>
              )}
              {text && <p>{text}</p>}
            </MessageContent>
          </Message>
        )
      })}
      {!busy && (
        <Button
          variant="outline"
          size="sm"
          className="mt-auto self-start"
          onClick={() => {
            setMessages([])
            sendMessage(question)
          }}
        >
          Replay
        </Button>
      )}
    </div>
  )
}
