          hugeicons="FileIcon"
          phosphor="FileIcon"
          remixicon="RiFileLine"
        />
        {name}
      </SidebarMenuButton>
    )
  }
  return (
    <SidebarMenuItem>
      <Collapsible
        className="group/collapsible [&[data-expanded]>button>svg:first-child]:rotate-90"
        defaultExpanded={name === "components" || name === "ui"}
